from functools import lru_cache
class Solution:
    def minimumTime(self, power: List[int]) -> int:
        n = len(power)
        @lru_cache(maxsize=None)
        def dfs(mask):
            if mask == (1 << n) - 1:
                return 0
            g = bin(mask).count('1') + 1
            best = float('inf')
            for i in range(n):
                if not mask & (1 << i):
                    cost = (power[i] + g - 1) // g
                    best = min(best, cost + dfs(mask | (1 << i)))
            return best
        return dfs(0)

