class Solution {
public:
    int minimumTime(vector<int>& power) {
        int n = power.size();
        vector<long long> dp(1 << n, -1);
        function<long long(int)> dfs = [&](int mask) -> long long {
            if (mask == (1 << n) - 1) return 0;
            if (dp[mask] != -1) return dp[mask];
            int g = __builtin_popcount(mask) + 1;
            long long best = LLONG_MAX;
            for (int i = 0; i < n; i++) {
                if (!(mask >> i & 1)) {
                    long long cost = ((long long)power[i] + g - 1) / g;
                    best = min(best, cost + dfs(mask | (1 << i)));
                }
            }
            return dp[mask] = best;
        };
        return (int)dfs(0);
    }
};

