class Solution {
    private int[] power;
    private int n;
    private long[] dp;

    public int minimumTime(int[] power) {
        this.power = power;
        this.n = power.length;
        this.dp = new long[1 << n];
        Arrays.fill(dp, -1);
        return (int) dfs(0);
    }

    private long dfs(int mask) {
        if (mask == (1 << n) - 1) return 0;
        if (dp[mask] != -1) return dp[mask];
        int g = Integer.bitCount(mask) + 1;
        long best = Long.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            if ((mask >> i & 1) == 0) {
                long cost = ((long) power[i] + g - 1) / g;
                best = Math.min(best, cost + dfs(mask | (1 << i)));
            }
        }
        return dp[mask] = best;
    }
}

