var minimumTime = function(power) {
    const n = power.length;
    const dp = new Array(1 << n).fill(-1);
    const bitCount = x => { let c = 0; while (x) { x &= x - 1; c++; } return c; };
    function dfs(mask) {
        if (mask === (1 << n) - 1) return 0;
        if (dp[mask] !== -1) return dp[mask];
        const g = bitCount(mask) + 1;
        let best = Infinity;
        for (let i = 0; i < n; i++) {
            if (!(mask >> i & 1)) {
                const cost = Math.ceil(power[i] / g);
                best = Math.min(best, cost + dfs(mask | (1 << i)));
            }
        }
        return dp[mask] = best;
    }
    return dfs(0);
};

