        INF = float('inf')
        dp = [INF] * (1 << n)
        dp[full] = 0
        for mask in range(full - 1, -1, -1):
            g = bin(mask).count('1') + 1
            cur = INF
            for i in range(n):
                if not mask & (1 << i):
                    cost = (power[i] + g - 1) // g
                    cur = min(cur, cost + dp[mask | (1 << i)])
            dp[mask] = cur
        return dp[0]

